SELECT id, symbol, interval_code, candle_open_time, decision, generated_at, created_at, TIMESTAMPDIFF(MICROSECOND, generated_at, created_at)/1000 AS gen_to_created_ms FROM trade_signal WHERE id IN (156721,156723,156850,156852,159285,159407,159408,159487,165412,165415,166819,166821,167668,168251,168277,171589,172201,172587,172588,176655,176710,176927,176934) ORDER BY symbol, generated_at